#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
echo "==> step192: seed player duration plans (1 Year / Lifetime) mapped to bot plan_keys"
D=$(mktemp /tmp/db192.XXXXXX.js); echo "" | base64 -d > "$D"
( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" GSZ_ENV="$GSZ/.env" node "$D" )
rm -f "$D"
echo "==> restarting (refresh storefront plan cache)"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000; for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    homepage $CODE"; false; }
echo "    homepage 200: OK (after ${i}s)"
echo ""
echo "==> step192 OK  Hot Player & IBO now show two duration pills (1 Year / Lifetime), each tied to its bot plan_key. Paid player orders auto-activate via /api/activate-player and deliver the credential block. Set each duration's price in Admin > Products (Lifetime defaulted to the 1-Year price for now)."
